class DListNode:
    """A singly linked list node used to track keys in the LRU cache."""
    def __init__(self, key: int):
        self.key = key
        self.next = None

class LRUCache:
    """Implements an LRU (Least Recently Used) cache using a hashmap for O(1) access
    combined with a singly linked list for maintaining the order of usage."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.head = DListNode(0)  # Dummy head
        self.tail = DListNode(0)  # Dummy tail
        self.head.next = self.tail
        self.size = 0

    def _remove_key(self, key: int) -> None:
        """Remove the node associated with the key from the linked list."""
        if key in self.cache:
            node = self.cache[key]
            prev_node = self.head
            # Find the previous node to remove this node
            while prev_node.next and prev_node.next != node:
                prev_node = prev_node.next
            if prev_node.next:
                prev_node.next = node.next
            del self.cache[key]
            self.size -= 1

    def _add_to_front(self, key: int) -> None:
        """Add a new node with the key to the front of the linked list."""
        new_node = DListNode(key)
        new_node.next = self.head.next
        self.head.next = new_node

    def get(self, key: int) -> int:
        """Retrieve a value from the cache by the key."""
        if key in self.cache:
            self._remove_key(key)
            self._add_to_front(key)
            return key  # Simulate returning the value associated with the key.
        return -1

    def put(self, key: int, value: int) -> None:
        """Insert or update the value of the key in the cache."""
        if key in self.cache:
            self._remove_key(key)
        self.cache[key] = value  # Store the value (here for demonstration)
        self._add_to_front(key)

        if self.size >= self.capacity:
            self._remove_key(self.head.next.key)  # Remove the least recently used key

class LRUCache:
    """Implements an LRU (Least Recently Used) cache using a dictionary for 
    key-value store and a list to maintain the order of usage."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def get(self, key: int) -> int:
        """Retrieve a value from the cache by the key, returning -1 if not found."""
        if key not in self.cache:
            return -1
        # Move the accessed key to the end (most recently used)
        self.keys.remove(key)
        self.keys.append(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        """Insert or update the value of the key in the cache."""
        if key in self.cache:
            # Update value and move to the end
            self.cache[key] = value
            self.keys.remove(key)
            self.keys.append(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used key
                lru_key = self.keys.pop(0)
                del self.cache[lru_key]
            # Add the new key-value pair
            self.cache[key] = value
            self.keys.append(key)
